/* _mm_cvtss_si64 / _mm_cvtsd_si64 round per MXCSR.RC. i686 has no 64-bit
 * CVTSS2SI/CVTSD2SI, and lccc's i686 fallback truncated (1.5 -> 1), which
 * is the cvtt* contract. It is now an exact emulation: one ADD/SUB pair with
 * copysign(2^23 or 2^52, x) below the integral threshold, and an exact cast
 * above it, up to the integer indefinite. The expected tables were produced
 * by the real x86-64 instructions (GCC 16.2 build) under all four rounding
 * modes. GCC and Clang offer these names only on x86-64, so the -m32 build
 * is lccc-only (.env) and self-checks against the tables. The x86-64
 * sibling compares with GCC as usual. */
#include <emmintrin.h>
#include <stdio.h>
static const float fv[] = {
	0.0f, -0.0f, 0.5f, -0.5f, 1.5f, -1.5f, 2.5f, -2.5f, 0.49999997f, -0.49999997f, 1e-45f, -1e-45f,
	8388607.5f, -8388607.5f, 0x1p23f, -0x1p23f, 8388609.0f, 16777215.0f, 2147483520.0f, 0x1p31f,
	-0x1p31f, 0x1p62f, 0x1.fffffep62f, -0x1p63f, 0x1p63f, -0x1.000002p63f, 1e30f, -1e30f,
	__builtin_inff(), -__builtin_inff(), __builtin_nanf(""), 1234567.25f, -1234567.75f, 3.5f, -7.5f,
};
#define NF (sizeof fv / sizeof fv[0])
static const double dv[] = {
	0.0, -0.0, 0.5, -0.5, 1.5, -1.5, 2.5, -2.5, 0.49999999999999994, -0.49999999999999994, 5e-324,
	-5e-324, 4503599627370495.5, -4503599627370495.5, 0x1p52, -0x1p52, 4503599627370497.0,
	2147483647.5, -2147483648.5, 2147483648.5, 0x1p62, 0x1.fffffffffffffp62, -0x1p63, 0x1p63,
	-0x1.0000000000001p63, 1e300, -1e300, __builtin_inf(), -__builtin_inf(), __builtin_nan(""),
	123456789012.5, -123456789012.5, 3.5, -7.5, 1099511627775.25, -1099511627775.75,
};
#define ND (sizeof dv / sizeof dv[0])
static const long long want_f[4][NF] = {
	{ 0LL, 0LL, 0LL, 0LL, 2LL, -2LL, 2LL, -2LL, 0LL, 0LL, 0LL, 0LL, 8388608LL, -8388608LL, 8388608LL, -8388608LL, 8388609LL, 16777215LL, 2147483520LL, 2147483648LL, -2147483648LL, 4611686018427387904LL, 9223371487098961920LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 1234567LL, -1234568LL, 4LL, -8LL, },
	{ 0LL, 0LL, 0LL, -1LL, 1LL, -2LL, 2LL, -3LL, 0LL, -1LL, 0LL, -1LL, 8388607LL, -8388608LL, 8388608LL, -8388608LL, 8388609LL, 16777215LL, 2147483520LL, 2147483648LL, -2147483648LL, 4611686018427387904LL, 9223371487098961920LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 1234567LL, -1234568LL, 3LL, -8LL, },
	{ 0LL, 0LL, 1LL, 0LL, 2LL, -1LL, 3LL, -2LL, 1LL, 0LL, 1LL, 0LL, 8388608LL, -8388607LL, 8388608LL, -8388608LL, 8388609LL, 16777215LL, 2147483520LL, 2147483648LL, -2147483648LL, 4611686018427387904LL, 9223371487098961920LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 1234568LL, -1234567LL, 4LL, -7LL, },
	{ 0LL, 0LL, 0LL, 0LL, 1LL, -1LL, 2LL, -2LL, 0LL, 0LL, 0LL, 0LL, 8388607LL, -8388607LL, 8388608LL, -8388608LL, 8388609LL, 16777215LL, 2147483520LL, 2147483648LL, -2147483648LL, 4611686018427387904LL, 9223371487098961920LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 1234567LL, -1234567LL, 3LL, -7LL, },
};
static const long long want_d[4][ND] = {
	{ 0LL, 0LL, 0LL, 0LL, 2LL, -2LL, 2LL, -2LL, 0LL, 0LL, 0LL, 0LL, 4503599627370496LL, -4503599627370496LL, 4503599627370496LL, -4503599627370496LL, 4503599627370497LL, 2147483648LL, -2147483648LL, 2147483648LL, 4611686018427387904LL, 9223372036854774784LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 123456789012LL, -123456789012LL, 4LL, -8LL, 1099511627775LL, -1099511627776LL, },
	{ 0LL, 0LL, 0LL, -1LL, 1LL, -2LL, 2LL, -3LL, 0LL, -1LL, 0LL, -1LL, 4503599627370495LL, -4503599627370496LL, 4503599627370496LL, -4503599627370496LL, 4503599627370497LL, 2147483647LL, -2147483649LL, 2147483648LL, 4611686018427387904LL, 9223372036854774784LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 123456789012LL, -123456789013LL, 3LL, -8LL, 1099511627775LL, -1099511627776LL, },
	{ 0LL, 0LL, 1LL, 0LL, 2LL, -1LL, 3LL, -2LL, 1LL, 0LL, 1LL, 0LL, 4503599627370496LL, -4503599627370495LL, 4503599627370496LL, -4503599627370496LL, 4503599627370497LL, 2147483648LL, -2147483648LL, 2147483649LL, 4611686018427387904LL, 9223372036854774784LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 123456789013LL, -123456789012LL, 4LL, -7LL, 1099511627776LL, -1099511627775LL, },
	{ 0LL, 0LL, 0LL, 0LL, 1LL, -1LL, 2LL, -2LL, 0LL, 0LL, 0LL, 0LL, 4503599627370495LL, -4503599627370495LL, 4503599627370496LL, -4503599627370496LL, 4503599627370497LL, 2147483647LL, -2147483648LL, 2147483648LL, 4611686018427387904LL, 9223372036854774784LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 123456789012LL, -123456789012LL, 3LL, -7LL, 1099511627775LL, -1099511627775LL, },
};
static const long long want_tf[NF] = { 0LL, 0LL, 0LL, 0LL, 1LL, -1LL, 2LL, -2LL, 0LL, 0LL, 0LL, 0LL, 8388607LL, -8388607LL, 8388608LL, -8388608LL, 8388609LL, 16777215LL, 2147483520LL, 2147483648LL, -2147483648LL, 4611686018427387904LL, 9223371487098961920LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 1234567LL, -1234567LL, 3LL, -7LL, };
static const long long want_td[ND] = { 0LL, 0LL, 0LL, 0LL, 1LL, -1LL, 2LL, -2LL, 0LL, 0LL, 0LL, 0LL, 4503599627370495LL, -4503599627370495LL, 4503599627370496LL, -4503599627370496LL, 4503599627370497LL, 2147483647LL, -2147483648LL, 2147483648LL, 4611686018427387904LL, 9223372036854774784LL, (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), (-9223372036854775807LL - 1), 123456789012LL, -123456789012LL, 3LL, -7LL, 1099511627775LL, -1099511627775LL, };

int main(void)
{
	static const unsigned modes[4] = { _MM_ROUND_NEAREST, _MM_ROUND_DOWN, _MM_ROUND_UP,
					   _MM_ROUND_TOWARD_ZERO };
	static const char *const name[4] = { "nearest", "down", "up", "zero" };
	int fail = 0;
	for (int m = 0; m < 4; m++) {
		_MM_SET_ROUNDING_MODE(modes[m]);
		for (unsigned i = 0; i < NF; i++) {
			long long got = _mm_cvtss_si64(_mm_set_ss(fv[i]));
			if (got != want_f[m][i]) {
				printf("FAIL cvtss_si64 %s [%u] %a: %lld want %lld\n", name[m], i, (double)fv[i], got,
				       want_f[m][i]);
				fail = 1;
			}
		}
		for (unsigned i = 0; i < ND; i++) {
			long long got = _mm_cvtsd_si64(_mm_set_sd(dv[i]));
			if (got != want_d[m][i]) {
				printf("FAIL cvtsd_si64 %s [%u] %a: %lld want %lld\n", name[m], i, dv[i], got,
				       want_d[m][i]);
				fail = 1;
			}
		}
	}
	_MM_SET_ROUNDING_MODE(_MM_ROUND_NEAREST);
	for (unsigned i = 0; i < NF; i++)
		if (_mm_cvttss_si64(_mm_set_ss(fv[i])) != want_tf[i]) {
			printf("FAIL cvttss_si64 [%u] %a\n", i, (double)fv[i]);
			fail = 1;
		}
	for (unsigned i = 0; i < ND; i++)
		if (_mm_cvttsd_si64(_mm_set_sd(dv[i])) != want_td[i]) {
			printf("FAIL cvttsd_si64 [%u] %a\n", i, dv[i]);
			fail = 1;
		}
	printf("cvt_si64 %s (%u floats, %u doubles, 4 modes)\n", fail ? "FAIL" : "ok", (unsigned)NF,
	       (unsigned)ND);
	return fail;
}
